import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

bn_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor bn2d_forward(torch::Tensor x,
                           torch::Tensor weight,
                           torch::Tensor bias,
                           torch::Tensor running_mean,
                           torch::Tensor running_var,
                           torch::Tensor num_batches_tracked,
                           bool training,
                           double momentum,
                           double eps);
"""

bn_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

constexpr int kThreads = 512;

// Single fused BatchNorm2d kernel.
// Phase 0 (training only): per-channel sum / sum-of-squares reduction.
// Phase 2: elementwise normalize y = x * scale[c] + shift[c], with the
// per-channel scale/shift recomputed in-register (fused Phase 1) and the
// running-stat update applied by one designated block per channel.
template <int Phase>
__global__ void bn2d_cute_kernel(
    const float4* __restrict__ X4,
    float4* __restrict__ Y4,
    const float*  __restrict__ Xs,
    float*        __restrict__ Ys,
    const float*  __restrict__ gamma,
    const float*  __restrict__ beta,
    float*        __restrict__ run_mean,
    float*        __restrict__ run_var,
    double*       __restrict__ sum,
    double*       __restrict__ sumsq,
    long*         __restrict__ nbt,
    int C, long NHW,
    float momentum, float eps, int training)
{
  const long V = NHW >> 2;  // number of float4 vectors per channel

  if constexpr (Phase == 0) {
    const int c = blockIdx.y;

    // CuTe global tensor view: (C, V) with contiguous inner mode
    Tensor mX = make_tensor(make_gmem_ptr(X4),
                            make_shape(C, V),
                            make_stride(V, Int<1>{}));

    // Unrolled reduction with four independent FP64 accumulator pairs.
    // This breaks the single lsum/lsq dependency chain and improves ILP while
    // preserving FP64 accumulation for the channel statistics.
    double lsum0 = 0.0, lsq0 = 0.0;
    double lsum1 = 0.0, lsq1 = 0.0;
    double lsum2 = 0.0, lsq2 = 0.0;
    double lsum3 = 0.0, lsq3 = 0.0;
    const long stride = (long)gridDim.x * blockDim.x;
    long v = (long)blockIdx.x * blockDim.x + threadIdx.x;
    for (; v + 3L * stride < V; v += 4L * stride) {
      const float4 x0 = __ldg(&mX(c, v));
      const float4 x1 = __ldg(&mX(c, v + stride));
      const float4 x2 = __ldg(&mX(c, v + 2L * stride));
      const float4 x3 = __ldg(&mX(c, v + 3L * stride));
      const float s001 = x0.x + x0.y;
      const float s023 = x0.z + x0.w;
      lsum0 += (double)(s001 + s023);
      const float q001 = x0.x * x0.x + x0.y * x0.y;
      const float q023 = x0.z * x0.z + x0.w * x0.w;
      lsq0 += (double)(q001 + q023);
      const float s101 = x1.x + x1.y;
      const float s123 = x1.z + x1.w;
      lsum1 += (double)(s101 + s123);
      const float q101 = x1.x * x1.x + x1.y * x1.y;
      const float q123 = x1.z * x1.z + x1.w * x1.w;
      lsq1 += (double)(q101 + q123);
      const float s201 = x2.x + x2.y;
      const float s223 = x2.z + x2.w;
      lsum2 += (double)(s201 + s223);
      const float q201 = x2.x * x2.x + x2.y * x2.y;
      const float q223 = x2.z * x2.z + x2.w * x2.w;
      lsq2 += (double)(q201 + q223);
      const float s301 = x3.x + x3.y;
      const float s323 = x3.z + x3.w;
      lsum3 += (double)(s301 + s323);
      const float q301 = x3.x * x3.x + x3.y * x3.y;
      const float q323 = x3.z * x3.z + x3.w * x3.w;
      lsq3 += (double)(q301 + q323);
    }
    for (; v < V; v += stride) {
      const float4 xv = __ldg(&mX(c, v));
      const float s01 = xv.x + xv.y;
      const float s23 = xv.z + xv.w;
      lsum0 += (double)(s01 + s23);
      const float q01 = xv.x * xv.x + xv.y * xv.y;
      const float q23 = xv.z * xv.z + xv.w * xv.w;
      lsq0 += (double)(q01 + q23);
    }
    double lsum = (lsum0 + lsum1) + (lsum2 + lsum3);
    double lsq  = (lsq0 + lsq1) + (lsq2 + lsq3);

    // scalar tail (NHW % 4), handled by first block of this channel
    const long tail = NHW & 3;
    if (tail && blockIdx.x == 0 && threadIdx.x < tail) {
      const long idx = (V << 2) + threadIdx.x;
      const float xv = __ldg(Xs + (long)c * NHW + idx);
      lsum += (double)xv;
      lsq  += (double)xv * xv;
    }

    // Warp-shuffle reduction first: avoids the full shared-memory tree and
    // most __syncthreads() barriers; shared memory is only used to combine
    // the kThreads/32 warp partials.
    const unsigned FULL_MASK = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
      lsum += __shfl_down_sync(FULL_MASK, lsum, offset);
      lsq  += __shfl_down_sync(FULL_MASK, lsq, offset);
    }
    constexpr int kWarps = kThreads / 32;
    __shared__ double s_sum[kWarps];
    __shared__ double s_sq[kWarps];
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    if (lane == 0) {
      s_sum[warp] = lsum;
      s_sq[warp]  = lsq;
    }
    __syncthreads();
    if (warp == 0) {
      lsum = (lane < kWarps) ? s_sum[lane] : 0.0;
      lsq  = (lane < kWarps) ? s_sq[lane]  : 0.0;
      for (int offset = 16; offset > 0; offset >>= 1) {
        lsum += __shfl_down_sync(FULL_MASK, lsum, offset);
        lsq  += __shfl_down_sync(FULL_MASK, lsq, offset);
      }
      if (lane == 0) {
        atomicAdd(&sum[c], lsum);
        atomicAdd(&sumsq[c], lsq);
      }
    }
  } else {
    const int c = blockIdx.y;
    // Fused Phase-1: recompute this channel's scale/shift in-register
    // (a few FLOPs per thread, identical in every block of the channel)
    // instead of a separate kernel launch that round-trips scale/shift
    // through global memory. Removes one kernel launch and two small
    // device allocations from the forward path.
    const double count = (double)NHW;
    double mean, var;
    if (training) {
      mean = sum[c] / count;
      var  = sumsq[c] / count - mean * mean;
      if (var < 0.0) var = 0.0;
    } else {
      mean = (double)run_mean[c];
      var  = (double)run_var[c];
    }
    const float invstd = rsqrtf((float)var + eps);
    const float g  = gamma ? gamma[c] : 1.0f;
    const float b  = beta  ? beta[c]  : 0.0f;
    const float sc = g * invstd;
    const float sh = b - (float)mean * sc;
    // One designated block per channel applies the running-stat update.
    if (training && blockIdx.x == 0 && threadIdx.x == 0) {
      const double unb = (count > 1.0) ? var * count / (count - 1.0) : 0.0;
      run_mean[c] = (float)((1.0 - (double)momentum) * (double)run_mean[c]
                            + (double)momentum * mean);
      run_var[c]  = (float)((1.0 - (double)momentum) * (double)run_var[c]
                            + (double)momentum * unb);
      if (c == 0 && nbt != nullptr) {
        *nbt += 1;
      }
    }

    Tensor mX = make_tensor(make_gmem_ptr(X4),
                            make_shape(C, V),
                            make_stride(V, Int<1>{}));
    Tensor mY = make_tensor(make_gmem_ptr(Y4),
                            make_shape(C, V),
                            make_stride(V, Int<1>{}));

    const long stride = (long)gridDim.x * blockDim.x;
    // Reverse sweep: start from the highest vector index of this channel
    // and walk down to zero. Phase 0 reads X with cache-normal (__ldg)
    // loads in ascending order, so the tail of each channel is the most
    // L2-resident region when this phase begins; consuming the hottest
    // data first converts a large fraction of the X re-read into L2 hits
    // instead of DRAM traffic (this kernel is DRAM-bound). Consecutive
    // threads still touch consecutive addresses (descending), so all
    // loads/stores remain fully coalesced.
    long v = (V - 1) - ((long)blockIdx.x * blockDim.x + threadIdx.x);
    // Unrolled streaming loop: four independent load/FMA/store groups per
    // iteration to increase memory-level parallelism and better saturate
    // DRAM bandwidth in this memory-bound elementwise phase.
    for (; v - 3L * stride >= 0; v -= 4L * stride) {
      const float4 x0 = __ldcs(&mX(c, v));
      const float4 x1 = __ldcs(&mX(c, v - stride));
      const float4 x2 = __ldcs(&mX(c, v - 2L * stride));
      const float4 x3 = __ldcs(&mX(c, v - 3L * stride));
      float4 y0, y1, y2, y3;
      y0.x = x0.x * sc + sh;
      y0.y = x0.y * sc + sh;
      y0.z = x0.z * sc + sh;
      y0.w = x0.w * sc + sh;
      y1.x = x1.x * sc + sh;
      y1.y = x1.y * sc + sh;
      y1.z = x1.z * sc + sh;
      y1.w = x1.w * sc + sh;
      y2.x = x2.x * sc + sh;
      y2.y = x2.y * sc + sh;
      y2.z = x2.z * sc + sh;
      y2.w = x2.w * sc + sh;
      y3.x = x3.x * sc + sh;
      y3.y = x3.y * sc + sh;
      y3.z = x3.z * sc + sh;
      y3.w = x3.w * sc + sh;
      __stcs(&mY(c, v), y0);
      __stcs(&mY(c, v - stride), y1);
      __stcs(&mY(c, v - 2L * stride), y2);
      __stcs(&mY(c, v - 3L * stride), y3);
    }
    for (; v >= 0; v -= stride) {
      float4 xv = __ldcs(&mX(c, v));  // hits L2-resident X left by Phase 0; evict-first after use
      float4 yv;
      yv.x = xv.x * sc + sh;
      yv.y = xv.y * sc + sh;
      yv.z = xv.z * sc + sh;
      yv.w = xv.w * sc + sh;
      __stcs(&mY(c, v), yv);  // streaming store: Y is written once, never re-read
    }

    const long tail = NHW & 3;
    if (tail && blockIdx.x == 0 && threadIdx.x < tail) {
      const long idx = (V << 2) + threadIdx.x;
      __stcs(Ys + (long)c * NHW + idx, __ldcs(Xs + (long)c * NHW + idx) * sc + sh);
    }
  }
}

torch::Tensor bn2d_forward(torch::Tensor x,
                           torch::Tensor weight,
                           torch::Tensor bias,
                           torch::Tensor running_mean,
                           torch::Tensor running_var,
                           torch::Tensor num_batches_tracked,
                           bool training,
                           double momentum,
                           double eps)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  auto b_c = bias.contiguous();
  TORCH_CHECK(running_mean.is_contiguous() && running_var.is_contiguous() &&
              num_batches_tracked.is_contiguous(),
              "running stats and num_batches_tracked must be contiguous");
  auto rm_c = running_mean;
  auto rv_c = running_var;
  auto nbt_c = num_batches_tracked;

  const long N = x_c.size(0);
  const long C = x_c.size(1);
  const long H = x_c.size(2);
  const long W = x_c.size(3);
  const long NHW = N * H * W;

  TORCH_CHECK(w_c.numel() == C && b_c.numel() == C, "affine params must have C elements");
  TORCH_CHECK(rm_c.numel() == C && rv_c.numel() == C, "running stats must have C elements");

  auto y = torch::empty_like(x_c);

  auto opts_d = torch::TensorOptions().dtype(torch::kFloat64).device(x.device());
  auto sum   = torch::zeros({C}, opts_d);
  auto sumsq = torch::zeros({C}, opts_d);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  const long V = NHW >> 2;
  long blocks_needed = (V + kThreads - 1) / kThreads;
  int gx = blocks_needed > 2048 ? 2048 : (int)blocks_needed;
  if (gx < 1) gx = 1;
  dim3 grid(gx, (unsigned)C);
  dim3 block(kThreads);

  const float4* X4 = reinterpret_cast<const float4*>(x_c.data_ptr<float>());
  float4*       Y4 = reinterpret_cast<float4*>(y.data_ptr<float>());
  const float*  Xs = x_c.data_ptr<float>();
  float*        Ys = y.data_ptr<float>();
  long* nbt_ptr = nbt_c.data_ptr<int64_t>();

  if (training) {
    bn2d_cute_kernel<0><<<grid, block, 0, stream>>>(
        X4, Y4, Xs, Ys,
        w_c.data_ptr<float>(), b_c.data_ptr<float>(),
        rm_c.data_ptr<float>(), rv_c.data_ptr<float>(),
        sum.data_ptr<double>(), sumsq.data_ptr<double>(),
        nbt_ptr,
        (int)C, NHW, (float)momentum, (float)eps, 1);
  }

  bn2d_cute_kernel<2><<<grid, block, 0, stream>>>(
      X4, Y4, Xs, Ys,
      w_c.data_ptr<float>(), b_c.data_ptr<float>(),
      rm_c.data_ptr<float>(), rv_c.data_ptr<float>(),
      sum.data_ptr<double>(), sumsq.data_ptr<double>(),
      nbt_ptr,
      (int)C, NHW, (float)momentum, (float)eps, training ? 1 : 0);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "bn2d_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
